 static final AtomicReference<ArtifactPolicy.State> verdict=new AtomicReference<>(ArtifactPolicy.State.CLEAN);
 @TestConfiguration static class ScannerFixture {@Bean @Primary MalwareScanner fixtureScanner(){return path->new MalwareScanner.Verdict(verdict.get(),"TEST_ONLY");}}
 @LocalServerPort int port;@Autowired JdbcTemplate jdbc;@Autowired PasswordEncoder passwords;@Autowired JsonMapper json;@Autowired ArtifactStorage store;
 UUID sales=UUID.randomUUID(),otherSales=UUID.randomUUID(),customer=UUID.randomUUID(),otherCustomer=UUID.randomUUID(),designer=UUID.randomUUID();String password=UUID.randomUUID().toString();Client seller,buyer,stranger,otherSeller,artist;List<UUID> leads=new ArrayList<>();
 byte[] pdf=validPdf(2);
 static byte[] validPdf(int count){try(var document=new org.apache.pdfbox.pdmodel.PDDocument();var bytes=new java.io.ByteArrayOutputStream()){for(int n=0;n<count;n++)document.addPage(new org.apache.pdfbox.pdmodel.PDPage());document.save(bytes);return bytes.toByteArray();}catch(Exception e){throw new IllegalStateException(e);}}
 @BeforeAll void seed()throws Exception{var users=List.of(sales,otherSales,customer,otherCustomer,designer);var roles=List.of("SALES","SALES","CUSTOMER","CUSTOMER","DESIGNER");for(int i=0;i<users.size();i++)jdbc.update("insert into staff_users(id,username,password_hash,role) values(?,?,?,?)",users.get(i),"it-proof-"+users.get(i)+"@example.test",passwords.encode(password),roles.get(i));seller=login(sales);buyer=login(customer);stranger=login(otherCustomer);otherSeller=login(otherSales);artist=login(designer);}
 @BeforeEach void reset(){verdict.set(ArtifactPolicy.State.CLEAN);}
 @AfterAll void cleanup()throws Exception{for(UUID id:List.of(sales,otherSales,customer,otherCustomer,designer))jdbc.update("update staff_users set enabled=false where id=?",id);for(UUID lead:leads)for(UUID file:jdbc.queryForList("select id from design_artifacts where enquiry_id=?",UUID.class,lead))store.discard(file);}
