 UUID lead(){UUID id=UUID.randomUUID();leads.add(id);jdbc.update("insert into enquiries(id,public_id,tracking_token_sha256,customer_name,email,phone,product_code,quantity,status,assigned_staff_id,customer_user_id,designer_id) values(?,?,?,'Synthetic proof customer','proof@example.test','9000000000','WEDDING_CARDS',250,'REVIEWING',?,?,?)",id,UUID.randomUUID(),"0".repeat(64),sales,customer,designer);return id;}
 UUID acceptQuote(UUID lead){UUID quote=UUID.randomUUID();jdbc.update("insert into quote_versions(id,enquiry_id,version,scope,total_paise,terms,proposed_date,valid_until,specification_snapshot,issued_by,state) values(?,?,1,'250 cards',100000,'Synthetic terms',current_date+10,current_date+3,'{}'::jsonb,?,'ACCEPTED')",quote,lead,sales);return quote;}
 String base(UUID id){return "/api/v1/design/enquiries/"+id;}
 Map<String,Object> data(HttpResponse<String> r){return json.readValue(r.body(),Map.class);}
 HttpResponse<String> upload(Client c,UUID lead,String kind,String name,String mime,byte[] bytes,boolean csrf)throws Exception{if(csrf)c.csrf();var request=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+base(lead)+"/artifacts?kind="+kind)).header("X-File-Name",URLEncoder.encode(name,StandardCharsets.UTF_8)).header("Content-Type",mime);if(csrf)request.header("X-CSRF-TOKEN",c.token);return c.client.send(request.POST(HttpRequest.BodyPublishers.ofByteArray(bytes)).build(),HttpResponse.BodyHandlers.ofString());}
 Map<String,Object> file(Client c,UUID lead)throws Exception{var r=upload(c,lead,"DESIGN","proof.pdf","application/pdf",pdf,true);assertEquals(201,r.statusCode(),r.body());return data(r);}
 Map<String,Object> publish(UUID lead,Object file,int version)throws Exception{var r=seller.send("POST",base(lead)+"/proofs",json.writeValueAsString(Map.of("artifactId",file,"expectedRevision",version,"summary","Updated names and layout")),true);assertEquals(200,r.statusCode(),r.body());return (Map<String,Object>)((List<?>)data(r).get("proofs")).getFirst();}
 String decision(Map<String,Object> proof,String action,String note){return json.writeValueAsString(Map.of("action",action,"note",note,"quoteId",proof.get("quote_id"),"artifactHash",proof.get("sha256"),"reviewed",true,"reviewedPages",List.of(1,2)));}
